import {costingApi} from "./costingApi";
import type {ManagementEvidence} from "./procurementApi";

export const pricingStatuses = ["Ожидает расчёта", "Себестоимость заполнена", "Себестоимость подтверждена", "Цена рассчитана", "На утверждении", "Цена утверждена", "Требует корректировки"];
export type PurchaseSnapshot = {sourceDocumentId: string | null; sourceDocumentNumber: string | null; invoiceLineId: number | null; originalUnitPrice: number | null; currency: string; fxRate: number | null; fxDate: string | null; fxSource: string; vatPercent: number | null; priceIncludesVat: boolean; recoverableVatPercent: number; purchaseUnit: string; baseUnit: string; unitsPerPurchaseUnit: number; confirmedDocument: boolean; manualReason: string; bynPerBaseUnit: number | null; bynExRecoverableVatPerBaseUnit: number | null; hasSource: boolean};
export type ReceiptCalculation = {id: string; firmId: number; receiptLineId: string; receiptId: string; productId: number; productName: string; gtin: string; supplier: string; warehouse: string; acceptedQuantity: number; postedAt: string; purchase: PurchaseSnapshot; purchaseId?: string | null; purchaseLineId?: string | null; managementEvidence?: ManagementEvidence | null; costByn: number | null; calculationNote: string; economist: string | null; confirmedAt: string | null; markupPercent: number | null; proposedPriceExVat: number | null; proposedPriceIncVat: number | null; salesVatPercent: number; roundingStep: number; status: number; version: number; stamp: string; updatedAt: string; events: {at: string; actor: string; action: string; note: string}[]};
export type PriceVersion = {id: string; productId: number; priceList: string; sourceProposalId: string; priceExVat: number; priceIncVat: number; vatPercent: number; baseUnit: string; effectiveFrom: string; effectiveTo: string | null; approvedAt: string; approvedBy: string; publishedAt: string | null};
export type ReceiptPricingRow = {calculation: ReceiptCalculation; currentPrice: PriceVersion | null; warnings: string[]};
export type PricingFilter = {search?: string; supplier?: string; warehouse?: string; receiptId?: string; document?: string; from?: string; to?: string; productId?: number; status?: number; sort?: string; descending?: boolean; page?: number; pageSize?: number};
export type PricingPolicyData = {minimumMarkup: number; maximumMarkup: number; allowNegativeMarkup: boolean; roundingStep: number; significantChangePercent: number; priceLists: string[]; grants: {userId: number; permissions: number}[]};
export type PricingAccess = {canEditCost: boolean; canSetMarkup: boolean; canApprove: boolean; canOverridePurchase: boolean; canManagePolicy: boolean; canManagePurchases?: boolean};
export type PolicyView = {policy: {firmId: number; stamp: string; data: PricingPolicyData}; access: PricingAccess; users: {id: number; name: string}[]};
export type PricingStage = Pick<ReceiptCalculation, "id" | "receiptId" | "productId" | "productName" | "gtin" | "status" | "version" | "postedAt">;
type Page<T> = {items: T[]; total: number; page: number; pageSize: number};
type Action = {id: string; stamp: string; action: "cost" | "confirm" | "markup" | "purchase" | "submit" | "approve" | "reject" | "revise"; cost?: string; note?: string; markup?: string; vatPercent?: string; purchase?: PurchaseSnapshot; reason?: string; effectiveFrom?: string | null; priceList?: string};
const api = costingApi.injectEndpoints({endpoints: b => ({
    receiptPricing: b.query<Page<ReceiptPricingRow>, PricingFilter>({query: params => ({url: "receipt-pricing", params}), providesTags: ["Costing"]}),
    receiptPricingRow: b.query<ReceiptPricingRow, string>({query: id => `receipt-pricing/${id}`, providesTags: ["Costing"]}),
    receiptPricingStages: b.query<Page<PricingStage>, PricingFilter>({query: params => ({url: "receipt-pricing/stages", params}), providesTags: ["Costing"]}),
    receiptPricingPolicy: b.query<PolicyView, void>({query: () => "receipt-pricing/policy", providesTags: ["Costing"]}),
    receiptPriceHistory: b.query<PriceVersion[], {productId: number; priceList?: string}>({query: ({productId, priceList = "default"}) => ({url: `receipt-pricing/products/${productId}/history`, params: {priceList}}), providesTags: ["Costing"]}),
    receiptPricingAction: b.mutation<ReceiptCalculation | PriceVersion, Action>({query: ({id, action, ...body}) => ({url: `receipt-pricing/${id}/${action}`, method: ["cost", "markup", "purchase"].includes(action) ? "PUT" : "POST", body}), invalidatesTags: ["Costing"]}),
    bulkReceiptMarkup: b.mutation<void, {rows: {id: string; stamp: string}[]; markup: string; vatPercent: string}>({query: body => ({url: "receipt-pricing/bulk-markup", method: "POST", body}), invalidatesTags: ["Costing"]}),
    saveReceiptPricingPolicy: b.mutation<PolicyView, {stamp: string; data: PricingPolicyData}>({query: body => ({url: "receipt-pricing/policy", method: "PUT", body}), invalidatesTags: ["Costing"]}),
    exportReceiptPricing: b.query<Blob, PricingFilter>({query: params => ({url: "receipt-pricing/export", params, responseHandler: response => response.blob()})}),
    receiptPricingAudit: b.query<{id: string; actor: string; action: string; note: string; at: string}[], void>({query: () => "receipt-pricing/audit", providesTags: ["Costing"]}),
})});
export const {useReceiptPricingQuery, useReceiptPricingRowQuery, useReceiptPricingStagesQuery, useReceiptPricingPolicyQuery, useReceiptPriceHistoryQuery, useReceiptPricingActionMutation, useBulkReceiptMarkupMutation, useSaveReceiptPricingPolicyMutation, useLazyExportReceiptPricingQuery, useReceiptPricingAuditQuery} = api;

// Preview uses scaled integers so decimal prices never pass through floating point arithmetic.
export function previewMarkup(cost: string, markup: string, roundingStep: string): string | null {
    const scale = BigInt(100000000);
    const parse = (value: string): bigint | null => {
        if (!/^-?\d+(?:[.,]\d{0,8})?$/.test(value)) return null;
        const negative = value.startsWith("-"); const [whole, part = ""] = value.replace("-", "").replace(",", ".").split(".");
        return (BigInt(whole) * scale + BigInt(part.padEnd(8, "0"))) * BigInt(negative ? -1 : 1);
    };
    const c = parse(cost); const m = parse(markup); const step = parse(roundingStep);
    if (c === null || m === null || step === null || c <= BigInt(0) || step <= BigInt(0) || m <= -BigInt(100) * scale) return null;
    const numerator = c * (BigInt(100) * scale + m); const denominator = BigInt(100) * scale * step;
    const units = numerator / denominator + (numerator % denominator * BigInt(2) >= denominator ? BigInt(1) : BigInt(0));
    const value = units * step; const fraction = (value % scale).toString().padStart(8, "0").replace(/0+$/, "");
    return `${value / scale}.${fraction.padEnd(2, "0")}`;
}
