import {EpassCard, EpassDraft, EpassField, EpassSchema, EpassSource} from './epassModels';

export const newCard = (values: Record<string, string> = {}): EpassCard => ({id: `${Date.now()}-${Math.random().toString(36).slice(2)}`, values});
export const today = () => {
    const date = new Date();
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
};
export const newDraft = (companyName = '', preparedBy = ''): EpassDraft => ({version: 1, templateId: 'zo-f03-feed',
    applicant: {companyName, preparedBy, gs1Number: '', requestDate: today(), phone: '', email: ''}, products: [newCard()]});
export const combinedName = (values: Record<string, string>, english = false): string => {
    const parts = (english ? ['R', 'S', 'Q', 'T'] : ['K', 'L', 'M', 'N']).map(key => (values[key] || '').trim());
    if (english && parts.some(Boolean)) {parts[0] = parts[0] ? parts[0].toUpperCase() : 'Unbranded'; parts[1] = parts[1].toUpperCase();}
    return parts.filter(Boolean).join(' ');
};
export const readDraft = (key: string, fallback: EpassDraft): {draft: EpassDraft; restored: boolean; error: string} => {
    try {
        const saved = localStorage.getItem(key);
        if (!saved) return {draft: fallback, restored: false, error: ''};
        const value = JSON.parse(saved) as EpassDraft;
        const isStringMap = (candidate: unknown) => typeof candidate === 'object' && candidate !== null && !Array.isArray(candidate)
            && Object.values(candidate).every(item => typeof item === 'string');
        if (value.version !== 1 || value.templateId !== fallback.templateId || !isStringMap(value.applicant)
            || !['companyName', 'preparedBy', 'requestDate', 'gs1Number', 'phone', 'email'].every(k => typeof (value.applicant as unknown as Record<string, unknown>)[k] === 'string')
            || !Array.isArray(value.products) || value.products.length < 1 || value.products.length > 1000
            || !value.products.every(p => p && typeof p.id === 'string' && isStringMap(p.values) && (p.sourceText === undefined || typeof p.sourceText === 'string') && (p.sourceName === undefined || typeof p.sourceName === 'string'))
            || new Set(value.products.map(p => p.id)).size !== value.products.length) throw new Error();
        return {draft: value, restored: true, error: ''};
    } catch {return {draft: fallback, restored: false, error: 'Сохраненный черновик не удалось прочитать. Начата новая заявка.'};}
};

export const normalizeSourceValue = (value: string, field: EpassField): string => {
    const trimmed = value.trim();
    if (field.type === 'date') {
        const match = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(trimmed);
        return match ? `${match[3]}-${match[2]}-${match[1]}` : trimmed;
    }
    if (!field.options.length) return trimmed;
    const lower = trimmed.toLowerCase();
    const option = field.options.find(o => [o.value, o.label].some(v => v.toLowerCase() === lower)
        || /\[([^\]]+)\]$/.exec(o.value)?.[1].toLowerCase() === lower
        || /\[([^\]]+)\]$/.exec(o.label)?.[1].toLowerCase() === lower);
    return option?.value || trimmed;
};
export const cardsFromSource = (source: EpassSource, mapping: Record<string, string>, schema: EpassSchema, selectedRows: Set<number>): EpassCard[] => {
    const fields = new Map(schema.fields.map(f => [f.key, f]));
    return source.rows.filter(row => selectedRows.has(row.rowNumber)).map(row => {
        const values: Record<string, string> = {};
        for (const column of source.columns) {
            const field = fields.get(mapping[column.key]);
            if (field && row.values[column.key]?.trim()) values[field.key] = normalizeSourceValue(row.values[column.key], field);
        }
        return {...newCard(values), sourceName: `${source.fileName}, строка ${row.rowNumber}`,
            sourceText: source.columns.filter(c => row.values[c.key]).map(c => `${c.header}: ${row.values[c.key]}`).join('\n').slice(0, 12000)};
    });
};
export const missingSuggestions = (card: EpassCard): string[] => {
    const fields: [string, string][] = [['AV', 'производитель'], ['AR', 'страна производства'], ['V', 'единица количества'], ['W', 'количество'], ['BD', 'состав'], ['BH', 'единица срока годности'], ['BI', 'срок годности'], ['CS', 'вид животного']];
    return fields.filter(([key]) => !card.values[key]?.trim()).map(([, label]) => label);
};
export const mergeSuggestions = (card: EpassCard, values: Record<string, string>, selected: Set<string>): EpassCard => ({...card,
    values: {...card.values, ...Object.fromEntries(Object.entries(values).filter(([key]) => selected.has(key)))}});
