import React, {useEffect, useRef, useState} from 'react';
import {Accordion, AccordionDetails, AccordionSummary, Alert, Box, Button, Checkbox, Chip, FormControlLabel, LinearProgress, MenuItem, Stack, Table, TableBody, TableCell, TableHead, TableRow, TextField, Typography} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import {Link, useParams} from 'react-router-dom';
import {MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, Surface} from '../../ui/commonStyled/commonStyled';
import {getActiveFirmId} from '../../api/config';
import {useAuth} from '../../auth/AuthContext';
import {store} from '../../store/store';
import {productsApi, useGetRecognitionCapabilitiesQuery} from '../products/productsApi';
import {warehouseReceiptsApi} from '../warehouse/warehouseReceiptsApi';
import {stockApi} from '../stock/stockApi';
import {goodsInvoicesApi} from '../transportWaybills/goodsInvoicesApi';
import OriginalInvoicePreview from '../transportWaybills/OriginalInvoicePreview';
import {newRequestId} from '../warehouse/receiptDraft';
import SupplyPaymentsPanel from './SupplyPaymentsPanel';
import {useReceiptPricingPolicyQuery} from '../costing/receiptPricingApi';
import {costingApi} from '../costing/costingApi';
import {documentKinds, documentLabels, InspectionLine, ShipmentLine, SupplyDocumentKind, SupplyLine, SupplyState, SupplyView, supplySteps} from './supplyModels';
import {downloadSupplyDocument, suppliesApi} from './suppliesApi';

const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value));
const numeric = (value: string) => Number(value.replace(',', '.')) || 0;
type FieldRow = {name: string; value: string};
const initialKind = (step: number): SupplyDocumentKind => step <= 3 ? 'SupplierOffer' : step <= 6 ? 'EpassResult' : step === 7 ? 'PurchaseInvoice' : step === 8 ? 'Cmr' : step === 9 ? 'Inspection' : 'PaymentProof';

export default function SupplyDetailPage({listPath = '/supplies'}: {listPath?: string}) {
    const id = useParams().id || ''; const {user} = useAuth();
    return <SupplyEditor key={`${getActiveFirmId()}.${user?.id}.${id}`} id={id} listPath={listPath}/>;
}
function SupplyEditor({id, listPath}: {id: string; listPath: string}) {
    const {isCompanyAdmin, isSuperAdmin} = useAuth(); const {data: pricingPolicy} = useReceiptPricingPolicyQuery(); const capabilities = useGetRecognitionCapabilitiesQuery();
    const [view, setView] = useState<SupplyView | null>(null); const latestView = useRef(view); latestView.current = view;
    const [draft, setDraft] = useState<SupplyState | null>(null); const [fields, setFields] = useState<Record<string, FieldRow[]>>({});
    const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
    const [dirty, setDirty] = useState(false); const [reloadRequired, setReloadRequired] = useState(false); const [visibleStep, setVisibleStep] = useState(1);
    const [kind, setKind] = useState<SupplyDocumentKind>('SupplierOffer'); const [file, setFile] = useState<{file: File; id: string} | null>(null);
    const [header, setHeader] = useState(1); const [useAi, setUseAi] = useState(true); const [registrationFile, setRegistrationFile] = useState('');
    const [mapping, setMapping] = useState<Record<string, number>>({}); const [shipmentFile, setShipmentFile] = useState('');
    const [reopenStep, setReopenStep] = useState(''); const [reopenReason, setReopenReason] = useState('');
    const apply = (result: SupplyView) => {
        const old = latestView.current; setView(result); latestView.current = result; setDraft(clone(result.supply.state)); setDirty(false); setReloadRequired(false); setVisibleStep(result.supply.state.step);
        setFields(Object.fromEntries(result.supply.state.lines.map(l => [l.id, Object.entries(l.fields).map(([name, value]) => ({name, value}))])));
        setKind(result.supply.state.completedAt ? 'PaymentProof' : initialKind(result.supply.state.step));
        setMapping(previous => Object.fromEntries(result.supply.state.lines.map(line => {
            const exact = result.supply.state.registrationRows.filter(r => (r.gtin === line.gtin && !!line.gtin) || r.name.trim().toLowerCase() === line.name.trim().toLowerCase());
            return [line.id, line.registrationRow || (old?.supply.state.registrationFileId === result.supply.state.registrationFileId ? previous[line.id] : undefined) || (exact.length === 1 ? exact[0].rowNumber : 0)];
        })));
    };
    useEffect(() => {
        const controller = new AbortController(); suppliesApi.get(id, controller.signal).then(result => {
            setView(result); latestView.current = result; setDraft(clone(result.supply.state)); setVisibleStep(result.supply.state.step); setKind(result.supply.state.completedAt ? 'PaymentProof' : initialKind(result.supply.state.step));
            setFields(Object.fromEntries(result.supply.state.lines.map(l => [l.id, Object.entries(l.fields).map(([name, value]) => ({name, value}))])));
            setMapping(Object.fromEntries(result.supply.state.lines.map(l => [l.id, l.registrationRow || 0])));
        }).catch((failure: Error) => {if (!controller.signal.aborted) setError(failure.message);}).finally(() => {if (!controller.signal.aborted) setLoading(false);});
        return () => controller.abort();
    }, [id]);
    useEffect(() => {
        if (!dirty) return;
        const prevent = (event: BeforeUnloadEvent) => {event.preventDefault(); event.returnValue = '';}; window.addEventListener('beforeunload', prevent);
        return () => window.removeEventListener('beforeunload', prevent);
    }, [dirty]);
    const change = (update: Partial<SupplyState>) => {setDraft(current => current && {...current, ...update}); setDirty(true);};
    const editLine = (lineId: string, update: Partial<SupplyLine>) => change({lines: draft!.lines.map(l => l.id === lineId ? {...l, ...update} : l)});
    const editShipment = (sourceId: number, update: Partial<ShipmentLine>) => change({shipmentLines: draft!.shipmentLines.map(l => l.sourceLineId === sourceId ? {...l, ...update} : l)});
    const editInspection = (sourceId: number, update: Partial<InspectionLine>) => change({inspection: {...draft!.inspection, lines: draft!.inspection.lines.map(l => l.sourceLineId === sourceId ? {...l, ...update} : l)}});
    const action = async (path: string, body: object = {}, method = 'POST', base = view!) => {
        const result = await suppliesApi.action(id, path, base.supply.version, body, method);
        store.dispatch(costingApi.util.invalidateTags(['Costing']));
        return result;
    };
    const saveDraft = async (): Promise<SupplyView> => {
        if (!view || !draft || !dirty) return view!;
        switch (view.supply.state.step) {
            case 3: {
                const lines = draft.lines.map(line => {
                    const pairs = fields[line.id] || []; if (pairs.some(f => !f.name.trim()) || new Set(pairs.map(f => f.name.trim().toLowerCase())).size !== pairs.length) throw new Error('Названия дополнительных полей должны быть заполнены и не повторяться.');
                    return {...line, fields: Object.fromEntries(pairs.map(f => [f.name.trim(), f.value]))};
                }); return action('lines', {lines}, 'PUT');
            }
            case 5: if (!draft.submittedOn) throw new Error('Укажите дату подачи заявки.'); return action('submission', {number: draft.registrationNumber, date: draft.submittedOn});
            case 7: return action('purchase', {purchase: draft.purchase}, 'PUT');
            case 8: return action('shipment', {lines: draft.shipmentLines}, 'PUT');
            case 9: return action('inspection', {inspection: draft.inspection}, 'PUT');
            default: return view;
        }
    };
    const run = async (work: () => Promise<SupplyView>) => {
        setBusy(true); setError('');
        try {apply(await work());}
        catch (failure) {
            setError((failure as Error).message);
            try {const fresh = await suppliesApi.get(id); if (!dirty) apply(fresh); else if (fresh.supply.version !== view?.supply.version) setReloadRequired(true);} catch { /* Keep the saved view and user edits while offline. */ }
        } finally {setBusy(false);}
    };
    const refresh = () => run(() => suppliesApi.get(id));
    const download = async (fileId: string, name: string) => {setBusy(true); setError(''); try {await downloadSupplyDocument(id, fileId, name);} catch (failure) {setError((failure as Error).message);} finally {setBusy(false);}};
    if (loading) return <MainDiv><LinearProgress/></MainDiv>;
    if (!view || !draft) return <MainDiv><Alert severity="error">{error || 'Поставка недоступна.'}</Alert><Button component={Link} to={listPath}>К поставкам</Button></MainDiv>;
    const state = view.supply.state; const current = visibleStep === state.step && !state.completedAt; const locked = busy || reloadRequired || !current;
    const files = (fileKind: SupplyDocumentKind) => view.documents.filter(d => d.kind === fileKind);
    const next = () => run(async () => action('advance', {}, 'POST', await saveDraft()));
    const upload = () => run(async () => {
        if (!file) throw new Error('Выберите файл.'); if (file.file.size === 0 || file.file.size > (kind === 'SupplierOffer' ? 10 : 25) * 1024 * 1024) throw new Error(kind === 'SupplierOffer' ? 'КП должно быть непустым и не больше 10 МБ.' : 'Документ должен быть непустым и не больше 25 МБ.');
        const base = await saveDraft(); const result = await suppliesApi.upload(id, base.supply.version, file.id, kind, file.file); setFile(null); return result;
    });
    const accepted = (lineId: string) => draft.inspection.lines.filter(l => !l.excluded && draft.shipmentLines.some(s => s.sourceLineId === l.sourceLineId && s.supplyLineId === lineId)).reduce((sum, l) => sum + l.actualQuantity, 0);
    return <MainDiv><Stack spacing={2}>
        <PageHeader><PageTitleGroup><PageTitle>{view.supply.title}</PageTitle><PageSubtitle>{view.supply.supplierName} · {state.completedAt ? 'Получено и оприходовано' : `Этап ${state.step} из 10: ${supplySteps[state.step - 1]}`}</PageSubtitle></PageTitleGroup>
            <Button component={Link} to={listPath}>Все поставки</Button></PageHeader>
        <LinearProgress variant="determinate" value={state.completedAt ? 100 : (state.step - 1) * 10}/>
        <Stack component="nav" aria-label="Маршрут поставки" direction="row" gap={1} flexWrap="wrap">{supplySteps.map((title, index) => <Button key={title} disabled={busy || dirty || index + 1 > state.step}
            variant={visibleStep === index + 1 ? 'contained' : 'outlined'} size="small" onClick={() => setVisibleStep(index + 1)}>{index + 1}. {title}{(index + 1 < state.step || state.completedAt) ? ' ✓' : ''}</Button>)}</Stack>
        <Stack direction="row" gap={1}><Button disabled={busy} onClick={refresh}>{dirty ? 'Перечитать и заменить несохранённые изменения' : 'Обновить поставку'}</Button><Button component={Link} to={`/catalogGeneration/lifecycle?step=${visibleStep}`}>Подсказка по этапу</Button></Stack>
        {busy && <LinearProgress/>}{error && <Alert severity="error" sx={{whiteSpace: 'pre-line'}}>{error}</Alert>}
        {reloadRequired && <Alert severity="warning">Поставка изменилась. Несохранённые данные оставлены на экране. Перечитайте поставку перед следующей записью.</Alert>}
        {dirty && <Alert severity="info">Есть несохранённые изменения. Сохранение, загрузка документа и переход вперёд сохранят данные этого этапа.</Alert>}
        {!current && !state.completedAt && <Alert severity="info">Просмотр завершённого этапа. Для исправления используйте возврат с причиной внизу карточки.</Alert>}
        <Surface><Stack spacing={2}><Typography variant="h6">{visibleStep}. {supplySteps[visibleStep - 1]}</Typography>
        <Box component="fieldset" disabled={locked} sx={{border: 0, p: 0, m: 0, minWidth: 0}}><Stack spacing={2}>
            {visibleStep === 1 && <>
                <Typography>Загрузите КП, каталог или фотографии поставщика в блоке документов ниже и выберите основной файл для распознавания.</Typography>
                <TextField select disabled={locked} label="Основной файл КП" value={state.offerFileId || ''} onChange={e => void run(() => action('source', {fileId: e.target.value}))}>{files('SupplierOffer').map(d => <MenuItem key={d.id} value={d.id}>{d.fileName}</MenuItem>)}</TextField>
            </>}
            {visibleStep === 2 && <>
                <Typography>ИИ распознаёт товары и переводит сведения на русский, сохраняя оригинал. Excel/CSV можно прочитать без ИИ; PDF и фото требуют подключённого ИИ.</Typography>
                {capabilities.data && !capabilities.data.aiAvailable && <Alert severity="info">ИИ не подключён. Для Excel/CSV доступно чтение колонок без перевода.</Alert>}
                <TextField label="Строка заголовков Excel/CSV" type="number" value={header} inputProps={{min: 1, max: 20}} onChange={e => setHeader(Number(e.target.value))}/>
                <FormControlLabel control={<Checkbox checked={useAi && capabilities.data?.aiAvailable === true} disabled={!capabilities.data?.aiAvailable} onChange={(_, value) => setUseAi(value)}/>} label="Распознавание и перевод с ИИ"/>
                <Button variant="contained" disabled={locked || capabilities.isLoading || capabilities.isError} onClick={() => void run(() => action('recognize', {headerRow: header, useAi: useAi && capabilities.data?.aiAvailable === true}))}>Распознать КП и подготовить товары</Button>
            </>}
            {visibleStep === 3 && <>
                {draft.warnings.map((warning, index) => <Alert key={index} severity="warning">{warning}</Alert>)}
                <Typography>Проверьте названия, состав, фасовку и сведения поставщика. Предложенная цена относится к закупке; цена продажи новой карточки будет 0.</Typography>
                {draft.lines.map((line, lineIndex) => <Accordion key={line.id} defaultExpanded={lineIndex === 0}><AccordionSummary expandIcon={<ExpandMoreIcon/>}>{lineIndex + 1}. {line.name || 'Новый товар'}</AccordionSummary><AccordionDetails><Stack spacing={2}>
                    <TextField label="Название товара" value={line.name} required onChange={e => editLine(line.id, {name: e.target.value})}/>
                    <TextField label="Описание" multiline value={line.description || ''} onChange={e => editLine(line.id, {description: e.target.value})}/>
                    <TextField label="Предложенная закупочная цена" type="number" value={line.suggestedPurchasePrice ?? ''} onChange={e => editLine(line.id, {suggestedPurchasePrice: numeric(e.target.value)})}/>
                    {line.warnings.map((warning, index) => <Alert key={index} severity="warning">{warning}</Alert>)}
                    <Typography fontWeight={700}>Дополнительные сведения</Typography>
                    {(fields[line.id] || []).map((field, index) => <Stack key={index} direction={{xs: 'column', sm: 'row'}} gap={1}>
                        <TextField label="Название поля" value={field.name} onChange={e => {setFields(previous => ({...previous, [line.id]: previous[line.id].map((f, i) => i === index ? {...f, name: e.target.value} : f)})); setDirty(true);}}/>
                        <TextField label="Значение поля" value={field.value} fullWidth onChange={e => {setFields(previous => ({...previous, [line.id]: previous[line.id].map((f, i) => i === index ? {...f, value: e.target.value} : f)})); setDirty(true);}}/>
                        <Button color="error" onClick={() => {setFields(previous => ({...previous, [line.id]: previous[line.id].filter((_, i) => i !== index)})); setDirty(true);}}>Убрать поле</Button>
                    </Stack>)}
                    <Button onClick={() => {setFields(previous => ({...previous, [line.id]: [...(previous[line.id] || []), {name: '', value: ''}]})); setDirty(true);}}>Добавить поле</Button>
                    <Typography fontWeight={700}>Характеристики</Typography>
                    {line.characteristics.map((field, index) => <Stack key={index} direction={{xs: 'column', sm: 'row'}} gap={1}>
                        <TextField label="Характеристика" value={field.name} onChange={e => editLine(line.id, {characteristics: line.characteristics.map((f, i) => i === index ? {...f, name: e.target.value} : f)})}/>
                        <TextField label="Значение характеристики" fullWidth value={field.value} onChange={e => editLine(line.id, {characteristics: line.characteristics.map((f, i) => i === index ? {...f, value: e.target.value} : f)})}/>
                        <Button color="error" onClick={() => editLine(line.id, {characteristics: line.characteristics.filter((_, i) => i !== index)})}>Убрать</Button>
                    </Stack>)}
                    <Button onClick={() => editLine(line.id, {characteristics: [...line.characteristics, {name: '', value: ''}]})}>Добавить характеристику</Button>
                    <details><summary>Исходные сведения</summary><Typography component="pre" sx={{whiteSpace: 'pre-wrap', overflowWrap: 'anywhere'}}>{line.rawText}</Typography></details>
                    <Button color="error" onClick={() => change({lines: draft.lines.filter(l => l.id !== line.id)})}>Исключить товар из поставки</Button>
                </Stack></AccordionDetails></Accordion>)}
                <Button onClick={() => {const lineId = newRequestId(); change({lines: [...draft.lines, {id: lineId, name: '', gtin: '', description: null, rawText: '', fields: {}, characteristics: [], epassValues: {}, suggestedPurchasePrice: null, warnings: [], registrationRow: null, productId: null}]}); setFields(previous => ({...previous, [lineId]: []}));}}>Добавить предварительный товар</Button>
            </>}
            {visibleStep === 4 && <>
                <Typography>Форма заполняется из проверенных товаров поставки. Сохранённая заявка доступна сотрудникам вашей компании на сервере.</Typography>
                <Button component={Link} to={`/catalogGeneration/epass?supply=${id}`} variant="contained" disabled={!current}>Открыть форму заявки ePASS</Button>
                <Typography variant="body2">После проверки и формирования Excel маршрут перейдёт к регистрации. Подача в ePASS выполняется человеком; её номер и результат фиксируются на следующем этапе.</Typography>
            </>}
            {visibleStep === 5 && <>
                <Alert severity="info">Скачайте готовую заявку в документах, подайте её в ePASS, затем сохраните номер обращения и загрузите официальный результат с GTIN.</Alert>
                <TextField label="Номер обращения ePASS" value={draft.registrationNumber} onChange={e => change({registrationNumber: e.target.value})}/>
                <TextField label="Дата подачи заявки" type="date" InputLabelProps={{shrink: true}} value={draft.submittedOn || ''} onChange={e => change({submittedOn: e.target.value || null})}/>
                <Button disabled={locked} onClick={() => void run(saveDraft)}>Сохранить подачу заявки</Button>
                <TextField select disabled={locked} label="Файл результата регистрации" value={registrationFile || draft.registrationFileId || ''} onChange={e => setRegistrationFile(e.target.value)}>{files('EpassResult').map(d => <MenuItem key={d.id} value={d.id}>{d.fileName}</MenuItem>)}</TextField>
                <Button disabled={locked || !(registrationFile || draft.registrationFileId)} onClick={() => void run(async () => action('registration/read', {fileId: registrationFile || draft.registrationFileId}, 'POST', await saveDraft()))}>Прочитать присвоенные GTIN</Button>
                {draft.registrationRows.length > 0 && <>
                    <Typography fontWeight={700}>Сопоставьте каждый товар с результатом регистрации</Typography>
                    {draft.lines.map(line => <TextField key={line.id} select disabled={locked} label={line.name} value={mapping[line.id] || line.registrationRow || ''} onChange={e => {setMapping(previous => ({...previous, [line.id]: Number(e.target.value)}));}}>
                        {draft.registrationRows.map(row => <MenuItem key={row.rowNumber} value={row.rowNumber}>{row.gtin} · {row.name}</MenuItem>)}</TextField>)}
                    <Button variant="contained" disabled={locked} onClick={() => void run(async () => action('registration/confirm', {mapping: draft.lines.map(l => ({lineId: l.id, rowNumber: mapping[l.id] || l.registrationRow || 0}))}, 'POST', await saveDraft()))}>Подтвердить регистрацию всех товаров</Button>
                </>}
            </>}
            {visibleStep === 6 && <>
                <Alert severity="info">Новые карточки получат GTIN и остаток 0. Существующие товары найдутся по GTIN. После прихода отпускная цена утверждается в разделе «Себестоимость и ценообразование».</Alert>
                {draft.lines.map(line => <Typography key={line.id}>{line.name} · GTIN {line.gtin}{line.productId ? ` · карточка #${line.productId}` : ''}</Typography>)}
                <Button variant="contained" disabled={locked} onClick={() => void run(async () => {
                    const result = await action('catalog'); store.dispatch(productsApi.util.invalidateTags(['Products', 'Product'])); return result;
                })}>{state.catalogStarted ? 'Повторить создание и восстановить результат' : 'Создать и связать карточки CRM'}</Button>
            </>}
            {visibleStep === 7 && view.financialsVisible === false && <Alert severity="info">Инвойс и финансовые данные доступны по правам. Приёмка не зависит от оплаты.</Alert>}
            {visibleStep === 7 && view.financialsVisible !== false && <>
                {view.paidTotal > 0 && <Alert severity="info">Инвойс и позиции закупки зафиксированы оплатами. Для исправления сначала аннулируйте ошибочные записи оплат с причиной.</Alert>}
                <Box component="fieldset" disabled={locked || view.paidTotal > 0 || !pricingPolicy?.access.canManagePurchases} sx={{border: 0, p: 0, m: 0, display: 'grid', gap: 2, minWidth: 0}}>
                <Stack direction={{xs: 'column', sm: 'row'}} gap={2}>
                    <TextField label="Номер инвойса поставщика" value={draft.purchase.invoiceNumber} onChange={e => change({purchase: {...draft.purchase, invoiceNumber: e.target.value}})}/>
                    <TextField label="Дата инвойса" type="date" InputLabelProps={{shrink: true}} value={draft.purchase.invoiceDate || ''} onChange={e => change({purchase: {...draft.purchase, invoiceDate: e.target.value || null}})}/>
                    <TextField label="Валюта (USD, CNY, EUR…)" value={draft.purchase.currency} inputProps={{maxLength: 3}} onChange={e => change({purchase: {...draft.purchase, currency: e.target.value.toUpperCase()}})}/>
                </Stack>
                <TextField select disabled={locked || view.paidTotal > 0} label="Инвойс на закупку" value={draft.purchase.invoiceFileId || ''} onChange={e => change({purchase: {...draft.purchase, invoiceFileId: e.target.value}})}>{files('PurchaseInvoice').map(d => <MenuItem key={d.id} value={d.id}>{d.fileName}</MenuItem>)}</TextField>
                <Button disabled={locked || !pricingPolicy?.access.canManagePurchases || view.paidTotal > 0 || !draft.purchase.invoiceFileId || draft.purchase.currency.length !== 3} onClick={() => void run(() => action('purchase/parse', {fileId: draft.purchase.invoiceFileId, currency: draft.purchase.currency}))}>Распознать строки инвойса в исходной валюте</Button>
                {draft.purchase.rateError && <Alert severity="warning">Справочный курс инвойса: {draft.purchase.rateError}. Приёмка не блокируется.</Alert>}
                {draft.purchase.invoiceRate && <Alert severity="info">НБРБ на дату инвойса: {draft.purchase.invoiceRate.scale} {draft.purchase.currency} = {draft.purchase.invoiceRate.officialRate} BYN. Это справочная оценка, фактические затраты определяются по платежам.</Alert>}
                {draft.purchase.lines.map((line, index) => <Surface key={line.lineId}><Stack gap={1}><Typography fontWeight={700}>{draft.lines.find(l => l.id === line.lineId)?.name}</Typography>
                    <Stack direction={{xs: 'column', sm: 'row'}} gap={1}>{(['quantity', 'unit', 'unitPrice'] as const).map(key => <TextField key={key} label={{quantity: 'Закупаемое количество', unit: 'Единица складского учёта', unitPrice: 'Закупочная цена'}[key]} value={line[key]} type={key === 'unit' ? 'text' : 'number'} inputProps={{min: 0, step: 'any'}}
                        onChange={e => change({purchase: {...draft.purchase, lines: draft.purchase.lines.map((l, i) => i === index ? {...l, [key]: key === 'unit' ? e.target.value : numeric(e.target.value)} : l)}})}/>)}</Stack>
                    <Stack direction={{xs: 'column', sm: 'row'}} gap={1}><TextField label="Базовая единица склада и цены" value={line.baseUnit ?? line.unit} onChange={e => change({purchase: {...draft.purchase, lines: draft.purchase.lines.map((l, i) => i === index ? {...l, baseUnit: e.target.value} : l)}})}/><TextField type="number" label="Базовых единиц в закупочной" value={line.unitsPerPurchaseUnit ?? 1} helperText="Бухта 100 м: единица закупки — бухта, базовая — м, коэффициент — 100" onChange={e => change({purchase: {...draft.purchase, lines: draft.purchase.lines.map((l, i) => i === index ? {...l, unitsPerPurchaseUnit: numeric(e.target.value), baseUnit: l.baseUnit || l.unit} : l)}})}/></Stack>
                    <Stack direction={{xs: 'column', sm: 'row'}} gap={1}>{([['vatPercent', 'НДС инвойса, %'], ['recoverableVatPercent', 'Возмещаемая доля НДС, %'], ['weightPerBaseUnit', 'Масса базовой единицы, кг'], ['volumePerBaseUnit', 'Объём базовой единицы, м³']] as const).map(([key, label]) => <TextField key={key} type="number" label={label} value={line[key] ?? (key === 'recoverableVatPercent' ? 100 : 0)} onChange={e => change({purchase: {...draft.purchase, lines: draft.purchase.lines.map((l, i) => i === index ? {...l, [key]: numeric(e.target.value)} : l)}})}/>)}</Stack>
                    <FormControlLabel label="Цена инвойса включает НДС" control={<Checkbox checked={line.priceIncludesVat ?? false} onChange={(_, checked) => change({purchase: {...draft.purchase, lines: draft.purchase.lines.map((l, i) => i === index ? {...l, priceIncludesVat: checked} : l)}})}/>}/>
                </Stack></Surface>)}
                <TextField label="Условия оплаты и поставки" multiline value={draft.purchase.terms} inputProps={{maxLength: 4000}} onChange={e => change({purchase: {...draft.purchase, terms: e.target.value}})}/>
                </Box>
            </>}
            {visibleStep === 8 && <>
                <Alert severity="info">Загрузите CMR, Invoice и Packing List. Для прихода выберите один основной документ или PDF с относящимися к одной поставке страницами. Остальные файлы остаются в комплекте; одинаковый груз не проводится по каждому файлу отдельно.</Alert>
                <TextField select disabled={locked} label="Основной документ отгрузки" value={shipmentFile || state.shipmentFileId || ''} onChange={e => setShipmentFile(e.target.value)}>{view.documents.filter(d => ['Cmr', 'Invoice', 'PackingList'].includes(d.kind)).map(d => <MenuItem key={d.id} value={d.id}>{documentLabels[d.kind]} · {d.fileName}</MenuItem>)}</TextField>
                <Button disabled={locked || !(shipmentFile || state.shipmentFileId)} onClick={() => void run(() => action('shipment/recognize', {fileId: shipmentFile || state.shipmentFileId}))}>Распознать и подготовить ожидаемое поступление</Button>
                {draft.shipmentLines.map(line => <Surface key={line.sourceLineId}><Stack spacing={1}>
                    <Typography fontWeight={700}>{line.name} · {line.expectedQuantity ?? 'Количество не распознано'} {line.unit} · {line.gtin || 'Без GTIN в документе'}</Typography>
                    <FormControlLabel control={<Checkbox checked={line.excluded} onChange={(_, value) => editShipment(line.sourceLineId, {excluded: value})}/>} label="Исключить строку из поступления"/>
                    {line.excluded ? <TextField label="Причина исключения" value={line.exclusionReason} onChange={e => editShipment(line.sourceLineId, {exclusionReason: e.target.value})}/>
                        : <TextField select disabled={locked} label="Товар этой поставки" value={line.supplyLineId || ''} onChange={e => editShipment(line.sourceLineId, {supplyLineId: e.target.value})}>{draft.lines.map(l => <MenuItem key={l.id} value={l.id}>{l.name} · {l.gtin}</MenuItem>)}</TextField>}
                </Stack></Surface>)}
            </>}
            {visibleStep === 9 && <>
                <Alert severity="info">Введите фактически принимаемое количество в единицах складского учёта. Для каждой принятой строки укажите партии. Повреждённый, просроченный и карантинный товар исключается из этого прихода.</Alert>
                {draft.inspection.lines.map(line => {
                    const source = draft.shipmentLines.find(s => s.sourceLineId === line.sourceLineId)!; const product = draft.lines.find(l => l.id === source.supplyLineId);
                    const purchaseLine = draft.purchase.lines.find(l => l.lineId === product?.id); const unit = purchaseLine?.baseUnit || purchaseLine?.unit;
                    return <Surface key={line.sourceLineId}><Stack spacing={1}>
                        <Typography fontWeight={700}>{product?.name || source.name} · по документу {source.expectedQuantity ?? '—'} {source.unit}</Typography>
                        <FormControlLabel control={<Checkbox checked={line.excluded} disabled={source.excluded} onChange={(_, value) => editInspection(line.sourceLineId, {excluded: value, actualQuantity: value ? 0 : line.actualQuantity, lots: value ? [] : line.lots})}/>} label="Не принимается на склад"/>
                        {!line.excluded && <>
                            <TextField label={`Фактически принято (${unit || 'единиц учёта'})`} type="number" value={line.actualQuantity} inputProps={{min: 0, step: 'any'}} onChange={e => {const quantity = numeric(e.target.value); editInspection(line.sourceLineId, {actualQuantity: quantity,
                                lots: line.lots.length === 0 ? [{batchNumber: '', quantity, expiryDate: null, condition: 'Accepted'}] : line.lots.length === 1 && (line.lots[0].quantity === line.actualQuantity || line.lots[0].quantity === 0) ? [{...line.lots[0], quantity}] : line.lots});}}/>
                            {line.lots.map((lot, index) => <Box key={index} sx={{display: 'grid', gridTemplateColumns: {xs: '1fr', md: 'repeat(2, minmax(0, 1fr))', xl: 'repeat(3, minmax(0, 1fr))'}, gap: 1}}>
                                <TextField label="Номер партии / маркировка" value={lot.batchNumber} onChange={e => editInspection(line.sourceLineId, {lots: line.lots.map((l, i) => i === index ? {...l, batchNumber: e.target.value} : l)})}/>
                                <TextField label="Количество в партии" type="number" value={lot.quantity} onChange={e => editInspection(line.sourceLineId, {lots: line.lots.map((l, i) => i === index ? {...l, quantity: numeric(e.target.value)} : l)})}/>
                                <TextField label="Годен до" type="date" InputLabelProps={{shrink: true}} value={lot.expiryDate || ''} onChange={e => editInspection(line.sourceLineId, {lots: line.lots.map((l, i) => i === index ? {...l, expiryDate: e.target.value || null} : l)})}/>
                                <TextField select disabled={locked} label="Состояние" value={lot.condition} sx={{minWidth: 160}} onChange={e => editInspection(line.sourceLineId, {lots: line.lots.map((l, i) => i === index ? {...l, condition: e.target.value} : l)})}><MenuItem value="Accepted">Годен</MenuItem><MenuItem value="Damaged">Повреждён</MenuItem><MenuItem value="Quarantine">Карантин</MenuItem></TextField>
                                <Button color="error" onClick={() => editInspection(line.sourceLineId, {lots: line.lots.filter((_, i) => i !== index)})}>Убрать партию</Button>
                            </Box>)}
                            <Button onClick={() => editInspection(line.sourceLineId, {lots: [...line.lots, {batchNumber: '', quantity: 0, expiryDate: null, condition: 'Accepted'}]})}>Добавить партию</Button>
                        </>}
                        <TextField label="Расхождение, пересчёт единиц или причина исключения" value={line.discrepancyReason} onChange={e => editInspection(line.sourceLineId, {discrepancyReason: e.target.value})}/>
                    </Stack></Surface>;
                })}
                <Table size="small"><TableHead><TableRow><TableCell>Товар</TableCell><TableCell>Закуплено</TableCell><TableCell>Принимается</TableCell></TableRow></TableHead><TableBody>{draft.purchase.lines.map(l => <TableRow key={l.lineId}><TableCell>{draft.lines.find(p => p.id === l.lineId)?.name}</TableCell><TableCell>{l.quantity} {l.unit}</TableCell><TableCell>{accepted(l.lineId)} {l.unit}</TableCell></TableRow>)}</TableBody></Table>
                <TextField label="Комментарий складской проверки" multiline value={draft.inspection.comment} inputProps={{maxLength: 4000}} helperText="Объясните отличия от закупки и не прибывшие товары. Принятые партии сохраняются в поставке; складской остаток ведётся по товару."
                    onChange={e => change({inspection: {...draft.inspection, comment: e.target.value}})}/>
                {([['quantityChecked', 'Фактическое количество проверено'], ['conditionChecked', 'Состояние и сроки годности проверены'], ['documentsChecked', 'Сопроводительные документы проверены']] as const).map(([key, label]) => <FormControlLabel key={key} control={<Checkbox checked={draft.inspection[key]} onChange={(_, value) => change({inspection: {...draft.inspection, [key]: value}})}/>} label={label}/>)}
            </>}
            {visibleStep === 10 && <>
                {state.completedAt ? <Alert severity="success">Приход проведён {new Date(state.completedAt).toLocaleString('ru-RU')}. Остатки обновлены. Повторное проведение этой поставки не создаст второй приход.</Alert> : <Alert severity="info">Складская проверка сохранена сотрудником #{state.inspection.inspectedByUserId}. После проведения CRM увеличит остатки на фактически принятое количество.</Alert>}
                {state.postingStarted && !state.completedAt && <Alert severity="warning">Состав зафиксирован для проведения. Если ответ был потерян, повторите действие: номер операции и количества сохраняются.</Alert>}
                {draft.inspection.lines.filter(l => !l.excluded).map(line => <Box key={line.sourceLineId}><Typography fontWeight={700}>{draft.lines.find(l => l.id === draft.shipmentLines.find(s => s.sourceLineId === line.sourceLineId)?.supplyLineId)?.name} · {line.actualQuantity}</Typography>
                    {line.lots.map((lot, index) => <Typography key={index} variant="body2">Партия {lot.batchNumber}: {lot.quantity}{lot.expiryDate ? ` · годен до ${lot.expiryDate}` : ''}</Typography>)}</Box>)}
                {!state.completedAt && (isCompanyAdmin || isSuperAdmin ? <Button variant="contained" disabled={locked} onClick={() => void run(async () => {
                    const result = await action('post'); store.dispatch(productsApi.util.invalidateTags(['Products', 'Product'])); store.dispatch(warehouseReceiptsApi.util.invalidateTags(['Receipts'])); store.dispatch(stockApi.util.invalidateTags(['Stock'])); store.dispatch(goodsInvoicesApi.util.invalidateTags(['Invoices'])); return result;
                })}>{state.postingStarted ? 'Повторить проведение и получить результат' : 'Провести приход и завершить маршрут'}</Button> : <Alert severity="info">Поставка готова к проведению. Одобрить приход может администратор компании.</Alert>)}
            </>}
        </Stack></Box>
        {current && [1, 3, 7, 8, 9].includes(state.step) && <Stack direction="row" gap={1} flexWrap="wrap">
            {dirty && <Button disabled={locked} onClick={() => void run(saveDraft)}>Сохранить данные этапа</Button>}
            <Button variant="contained" disabled={locked} onClick={next}>{state.step === 9 ? 'Подтвердить складскую проверку' : 'Сохранить и перейти к следующему этапу'}</Button>
        </Stack>}
        </Stack></Surface>
        {state.step >= 7 && <Surface><SupplyPaymentsPanel view={view} busy={busy} save={async (path, body) => {const result = await action(path, body, "POST", await saveDraft()); apply(result); return result;}}/></Surface>}
        {[8, 9, 10].includes(visibleStep) && state.transportWaybillId && <OriginalInvoicePreview id={state.transportWaybillId}/>}
        <Surface><Stack spacing={2}><Typography variant="h6">Документы поставки</Typography>
            {((state.step < 10 && !state.completedAt) || pricingPolicy?.access.canManagePurchases) && <Stack direction={{xs: 'column', sm: 'row'}} gap={1}>
                <TextField select label="Назначение документа" value={kind} disabled={busy || reloadRequired} sx={{minWidth: 230}} onChange={e => setKind(e.target.value as SupplyDocumentKind)}>{documentKinds.filter(k => k !== 'EpassApplication' && (state.step < 10 || k === 'PaymentProof')).map(k => <MenuItem key={k} value={k}>{documentLabels[k]}</MenuItem>)}</TextField>
                <Button component="label" variant="outlined" disabled={busy || reloadRequired}>{file?.file.name || 'Выбрать файл'}<input type="file" hidden aria-label="Документ поставки" accept=".pdf,.xls,.xlsx,.csv,.jpg,.jpeg,.png,.webp" onChange={e => {const nextFile = e.target.files?.[0]; setFile(nextFile ? {file: nextFile, id: newRequestId()} : null); e.target.value = '';}}/></Button>
                <Button variant="contained" disabled={busy || reloadRequired || !file} onClick={upload}>Загрузить в поставку</Button>
            </Stack>}
            {view.documents.map(doc => <Stack key={doc.id} direction="row" gap={1} flexWrap="wrap" alignItems="center"><Chip size="small" label={documentLabels[doc.kind]}/><Typography sx={{overflowWrap: 'anywhere'}}>{doc.fileName} · {(doc.size / 1024).toFixed(0)} КБ</Typography><Button disabled={busy} onClick={() => void download(doc.id, doc.fileName)}>Скачать</Button></Stack>)}
            {!view.documents.length && <Typography color="text.secondary">Документы ещё не загружены.</Typography>}
        </Stack></Surface>
        <Stack direction="row" gap={1} flexWrap="wrap">
            {state.transportWaybillId && <Button component={Link} to={`/invoices/${state.transportWaybillId}`}>Данные накладной</Button>}
            {state.receiptId && <Button component={Link} to={`/invoices/receipts/${state.receiptId}`}>Сохранённый приход</Button>}
            {!!state.lines.some(l => l.productId) && <Button component={Link} to="/productsManagement">Карточки каталога</Button>}
            {state.completedAt && <Button component={Link} to="/stockManagement">Проверить остатки</Button>}
        </Stack>
        {!state.completedAt && !state.postingStarted && state.step > 1 && <Accordion><AccordionSummary expandIcon={<ExpandMoreIcon/>}>Вернуться к предыдущему этапу для исправления</AccordionSummary><AccordionDetails><Stack spacing={2}>
            <Alert severity="warning">Последующие проверки потребуется пройти заново. Документы и история сохранятся. После создания карточек возврат доступен начиная с закупки.</Alert>
            <TextField select label="Этап для исправления" value={reopenStep} disabled={busy} onChange={e => setReopenStep(e.target.value)}>{supplySteps.map((title, index) => index + 1 < state.step && (!state.catalogStarted || index + 1 >= 7) ? <MenuItem key={title} value={index + 1}>{index + 1}. {title}</MenuItem> : null)}</TextField>
            <TextField label="Причина возврата" value={reopenReason} inputProps={{maxLength: 500}} disabled={busy} onChange={e => setReopenReason(e.target.value)}/>
            <Button disabled={busy || reloadRequired || !reopenStep || !reopenReason.trim()} color="warning" onClick={() => void run(() => action('reopen', {step: Number(reopenStep), reason: reopenReason}))}>Вернуть поставку на выбранный этап</Button>
        </Stack></AccordionDetails></Accordion>}
        <Accordion><AccordionSummary expandIcon={<ExpandMoreIcon/>}>История прохождения маршрута</AccordionSummary><AccordionDetails><Stack spacing={1}>{view.history.map(event => <Box key={event.id}><Typography>{event.action}</Typography><Typography variant="caption" color="text.secondary">{new Date(event.at).toLocaleString('ru-RU')} · сотрудник #{event.actorUserId} · этап {event.step}</Typography></Box>)}</Stack></AccordionDetails></Accordion>
    </Stack></MainDiv>;
}
