import React, {useEffect, useState} from "react";
import {Alert, Button, CircularProgress, Paper, Stack} from "@mui/material";
import {getApiErrorMessage} from "../../api/errors";
import {useOriginalGoodsInvoiceMutation} from "./goodsInvoicesApi";
function Viewer({id}: {id: number}) {
    const [load] = useOriginalGoodsInvoiceMutation(); const [source,setSource] = useState<{url: string; type: string} | null>(null);
    const [error,setError] = useState(""); const [rotation,setRotation] = useState(0);
    useEffect(() => {
        let active = true; let url: string | undefined;
        void load(id).unwrap().then(blob => {if (active) {url = URL.createObjectURL(blob);setSource({url,type:blob.type});}}).catch(failure => {if (active) setError(getApiErrorMessage(failure,"Исходный файл недоступен."));});
        return () => {active = false;if (url) URL.revokeObjectURL(url);};
    },[id,load]);
    if (error) return <Alert severity="error">{error}</Alert>;
    if (!source) return <CircularProgress/>;
    return <Stack spacing={1}><Button component="a" href={source.url} download={`Приход-${id}`}>Скачать оригинал</Button>
        {source.type === "application/pdf" ? <iframe title="Оригинал файла для прихода" src={source.url} style={{width:"100%",height:"70vh",border:0}}/> : <><Button onClick={() => setRotation((rotation+90)%360)}>Повернуть изображение</Button><Paper variant="outlined" sx={{height:"70vh",display:"flex",alignItems:"center",justifyContent:"center",overflow:"auto"}}><img alt="Оригинал файла для прихода" src={source.url} style={{maxWidth:rotation%180 ? "52vh" : "100%",maxHeight:"65vh",objectFit:"contain",transform:`rotate(${rotation}deg)`}}/></Paper></>}
    </Stack>;
}
export default function OriginalInvoicePreview({id}: {id: number}) {
    const [open,setOpen] = useState(false);
    return <Stack spacing={1}><Button onClick={() => setOpen(!open)}>{open ? "Скрыть оригинал" : "Посмотреть оригинал файла для прихода"}</Button>{open && <Viewer key={id} id={id}/>}</Stack>;
}
