export const supplySteps = ['Получение КП поставщика', 'Распознавание и перевод', 'Предварительная номенклатура', 'Заявка ePASS', 'Регистрация и GTIN', 'Карточки CRM', 'Закупка и оплата', 'Документы отгрузки', 'Приёмка на складе', 'Оприходование'];
export const documentKinds = ['SupplierOffer', 'EpassApplication', 'EpassResult', 'PurchaseInvoice', 'PaymentProof', 'Cmr', 'Invoice', 'PackingList', 'Inspection', 'Other'] as const;
export type SupplyDocumentKind = typeof documentKinds[number];
export const documentLabels: Record<SupplyDocumentKind, string> = {SupplierOffer: 'КП поставщика', EpassApplication: 'Заявка ePASS', EpassResult: 'Результат регистрации ePASS', PurchaseInvoice: 'Инвойс на закупку', PaymentProof: 'Подтверждение оплаты', Cmr: 'CMR / ТТН', Invoice: 'Инвойс отгрузки', PackingList: 'Packing List', Inspection: 'Документ приёмки', Other: 'Другой документ'};
export interface SupplyLine {
    id: string; name: string; gtin: string; description: string | null; rawText: string; fields: Record<string, string>;
    characteristics: {name: string; value: string}[]; epassValues: Record<string, string>; suggestedPurchasePrice: number | null;
    warnings: string[]; registrationRow: number | null; productId: number | null;
}
export interface SupplyRateSnapshot {id: string; currency: string; effectiveDate: string; scale: number; officialRate: number; source: string; retrievedAt: string; manualReason: string}
export interface PurchaseLine {lineId: string; quantity: number; unit: string; unitPrice: number; baseUnit?: string | null; unitsPerPurchaseUnit?: number; vatPercent?: number; priceIncludesVat?: boolean; recoverableVatPercent?: number; weightPerBaseUnit?: number; volumePerBaseUnit?: number}
export interface SupplyPurchase {invoiceNumber: string; invoiceDate: string | null; invoiceFileId: string | null; currency: string; terms: string; lines: PurchaseLine[]; invoiceRate?: SupplyRateSnapshot | null; rateError?: string}
export interface SupplyPayment {id: string; amount: number; date: string; reference: string; proofFileId: string; recordedByUserId: number; recordedAt: string; voidReason: string | null; actualByn?: number | null; bankRate?: number | null; officialRate?: SupplyRateSnapshot | null; rateError?: string}
export interface ShipmentLine {sourceLineId: number; name: string; gtin: string; unit: string; expectedQuantity: number | null; supplyLineId: string | null; excluded: boolean; exclusionReason: string}
export interface SupplyLot {batchNumber: string; quantity: number; expiryDate: string | null; condition: string}
export interface InspectionLine {sourceLineId: number; actualQuantity: number; excluded: boolean; discrepancyReason: string; lots: SupplyLot[]}
export interface SupplyInspection {lines: InspectionLine[]; quantityChecked: boolean; conditionChecked: boolean; documentsChecked: boolean; comment: string; inspectedByUserId: number | null; inspectedAt: string | null}
export interface SupplyState {
    step: number; offerFileId: string | null; recognitionBatchId: string | null; lines: SupplyLine[]; warnings: string[];
    epassApplicationJson: string; epassApplicationFileId: string | null; registrationNumber: string; submittedOn: string | null;
    registrationFileId: string | null; registrationRows: {rowNumber: number; gtin: string; name: string; fields: Record<string, string>}[];
    purchase: SupplyPurchase; payments: SupplyPayment[]; transportWaybillId: number | null; shipmentFileId: string | null; invoiceApprovalVersion: string;
    shipmentLines: ShipmentLine[]; inspection: SupplyInspection; catalogStarted: boolean; postingStarted: boolean; receiptId: string | null; completedAt: string | null;
}
export interface SupplyCase {id: string; firmId: number; title: string; supplierName: string; categoryId: number; createdByUserId: number; createdAt: string; updatedAt: string; version: string; state: SupplyState}
export interface SupplyDocument {id: string; kind: SupplyDocumentKind; fileName: string; contentType: string; size: number; uploadedByUserId: number; uploadedAt: string}
export interface SupplyView {supply: SupplyCase; documents: SupplyDocument[]; history: {id: string; actorUserId: number; step: number; action: string; at: string}[]; purchaseTotal: number; paidTotal: number; financialsVisible?: boolean}
export interface SupplySummary {id: string; title: string; supplierName: string; step: number; completed: boolean; updatedAt: string}
