import React, {useState} from 'react';
import {Alert, Button, MenuItem, Stack, TextField, Typography} from '@mui/material';
import {Link} from 'react-router-dom';
import {SupplyView} from './supplyModels';
import {newRequestId} from '../warehouse/receiptDraft';
import {today} from '../catalogGeneration/epass/epassDraft';
import {useReceiptPricingPolicyQuery} from '../costing/receiptPricingApi';

export default function SupplyPaymentsPanel({view, busy, save}: {view: SupplyView; busy: boolean; save: (path: string, body: object) => Promise<unknown>}) {
    const {data: policy} = useReceiptPricingPolicyQuery(); const permitted = !!policy?.access.canManagePurchases;
    const [payment, setPayment] = useState({id: newRequestId(), amount: '', actualByn: '', bankRate: '', date: today(), reference: '', proofFileId: ''});
    const [reason, setReason] = useState(''); const [error, setError] = useState('');
    const [sending, setSending] = useState(false); busy = busy || sending;
    if (view.financialsVisible === false) return <Alert severity="info">Финансовые реквизиты закупки доступны по назначенным правам. Физическая приёмка от готовности расчёта не зависит.</Alert>;
    const run = async (work: () => Promise<unknown>) => {setError(''); setSending(true); try {await work();} catch (e) {setError((e as Error).message);} finally {setSending(false);}};
    return <Stack spacing={2}><Typography variant="h6">Оплаты и фактические затраты BYN</Typography>
        <Alert severity="info">Оплаты можно дополнять после отгрузки и прихода. Если фактическая стоимость валюты неизвестна, оставьте BYN пустым: расчёт будет предварительным. Курс банка и НБРБ сохраняются отдельно.</Alert>
        {error && <Alert severity="error">{error}</Alert>}<Typography>Инвойс: {view.purchaseTotal.toLocaleString('ru-RU')} {view.supply.state.purchase.currency} · оплачено: {view.paidTotal.toLocaleString('ru-RU')}</Typography>
        {permitted ? <><div className="cost-fields"><TextField label="Сумма оплаты" value={payment.amount} inputProps={{inputMode: 'decimal'}} onChange={e => setPayment(p => ({...p, amount: e.target.value}))}/><TextField label="Фактически списано BYN" value={payment.actualByn} inputProps={{inputMode: 'decimal'}} onChange={e => setPayment(p => ({...p, actualByn: e.target.value}))}/><TextField label="Курс банка за 1 единицу валюты" value={payment.bankRate} inputProps={{inputMode: 'decimal'}} onChange={e => setPayment(p => ({...p, bankRate: e.target.value}))}/><TextField label="Дата оплаты" type="date" InputLabelProps={{shrink: true}} value={payment.date} onChange={e => setPayment(p => ({...p, date: e.target.value}))}/><TextField label="Номер платёжного документа" value={payment.reference} onChange={e => setPayment(p => ({...p, reference: e.target.value}))}/><TextField select label="Подтверждение оплаты" value={payment.proofFileId} onChange={e => setPayment(p => ({...p, proofFileId: e.target.value}))}>{view.documents.filter(d => d.kind === 'PaymentProof').map(d => <MenuItem key={d.id} value={d.id}>{d.fileName}</MenuItem>)}</TextField></div>
            <Button disabled={busy || !payment.amount || !payment.reference || !payment.proofFileId} onClick={() => void run(async () => {await save('payments', {...payment, amount: payment.amount.replace(',', '.'), actualByn: payment.actualByn ? payment.actualByn.replace(',', '.') : null, bankRate: payment.bankRate ? payment.bankRate.replace(',', '.') : null}); setPayment({id: newRequestId(), amount: '', actualByn: '', bankRate: '', date: today(), reference: '', proofFileId: ''});})}>Зарегистрировать оплату</Button></> : <Alert severity="info">Для записи платежей администратор должен назначить право «Закупки и оплаты».</Alert>}
        {view.supply.state.payments.map(p => <Stack key={p.id} gap={1}><Typography>{p.reference} · {p.date} · {p.amount} {view.supply.state.purchase.currency}; фактически {p.actualByn ?? 'не указано'} BYN; банк {p.bankRate ?? '—'}</Typography>{p.officialRate && <Typography variant="body2">НБРБ: {p.officialRate.scale} {p.officialRate.currency} = {p.officialRate.officialRate} BYN на {p.officialRate.effectiveDate}</Typography>}{p.rateError && <Alert severity="warning">{p.rateError}</Alert>}{p.voidReason ? <Typography>Аннулирована: {p.voidReason}</Typography> : permitted && <Button color="error" disabled={busy || !reason.trim()} onClick={() => void run(() => save(`payments/${p.id}/void`, {reason}))}>Аннулировать ошибочную запись</Button>}</Stack>)}
        {permitted && !!view.supply.state.payments.length && <TextField label="Причина исправления записи оплаты" value={reason} onChange={e => setReason(e.target.value)}/>}
        <Button component={Link} to={`/costing?purchaseId=${view.supply.id}`}>Управленческая стоимость и расходы партий</Button>
    </Stack>;
}
